<template><section class="coverage-section">
 <p class="coverage-intro">{{ defensive?'Types reçus : résistances et immunités de tes compagnons, talents de type et corruption compris.':'Types adverses : réponses super efficaces parmi les quatre capacités actuellement équipées. Chaque réponse correspond à un Pokémon différent.' }}</p>
 <div class="coverage-grid"><button v-for="row in rows" :key="row.type" :class="tone(row)" :aria-expanded="selected===row.type" @click="selected=selected===row.type?null:row.type" :data-coverage-type="row.type"><pokemon-type-icon :type="row.type"/><strong>{{ typeName(row.type) }}</strong><b>{{ value(row) }}</b><small>{{ caption(row) }}</small></button></div>
 <article v-if="details" class="coverage-details" role="status"><h4>{{ typeName(details.type) }}</h4><p v-for="(p,i) in team" :key="p.uuid||i"><span>{{ p.name || p.truename || p.data?.name?.french }}</span><b>{{ defensive?format(details.multipliers[i]):best(p,details.type) }}</b></p></article>
 <p class="coverage-note">{{ defensive?'Les multiplicateurs concernent une attaque sans talent offensif adverse ni contexte météo. Les protections conditionnelles (Multiécaille, Fermeté, contact…) ne sont pas des résistances de type.':'Lecture face à un type simple, sans talent adverse. Un double type peut modifier le résultat. Les capacités de statut ne comptent pas.' }}</p>
</section></template>
<script>
import PokemonTypeIcon from '../PokemonTypeIcon.vue';
import {individualOffense} from '@/services/teamCoverage';
import {localizeMoveName} from '@/services/i18n';
import {localizeTypeName} from '@/services/pokemonTypes';
export default{components:{PokemonTypeIcon},props:{analysis:Object,team:Array,defensive:Boolean},data:()=>({selected:null}),computed:{rows(){return this.defensive?this.analysis.defense:this.analysis.offense;},details(){return this.rows.find(r=>r.type===this.selected);}},methods:{typeName:localizeTypeName,format:n=>'×'+String(n).replace('.',','),best(p,t){const list=individualOffense(p,t);return list.length?this.format(list[0].multiplier)+' · '+localizeMoveName(list[0].name,'fr'):'Aucune attaque';},value(r){return this.team.length===1?this.format(this.defensive?r.multipliers[0]:r.best):this.defensive?r.immune+' immun.':r.count+' réponse'+(r.count>1?'s':'');},caption(r){return this.defensive?`${r.weak} faible${r.weak>1?'s':''} · ${r.resist} résiste${r.resist>1?'nt':''}`:r.best>1?'Super efficace':r.best===1?'Dégâts neutres':r.best>0?'Résisté':'Aucune réponse';},tone(r){return this.defensive?r.weak>this.team.length/2?'is-danger':r.immune+r.resist>0?'is-good':'is-neutral':r.count>=2?'is-good':r.count===1?'is-covered':'is-danger';}}};
</script>
<style scoped>
.coverage-intro,.coverage-note{font-size:12px;line-height:1.65;color:var(--journal-muted);margin:0 0 15px}.coverage-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px}.coverage-grid button{min-width:0;border:1px solid var(--journal-border);border-radius:9px;padding:11px 5px;background:var(--journal-card);color:var(--journal-ink);font:11px var(--journal-font);display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer;min-height:106px}.coverage-grid strong{font-size:12px}.coverage-grid b{font-size:11px}.coverage-grid small{font-size:9px;color:var(--journal-muted)}.coverage-grid .is-good{border-bottom:3px solid #67a88b;background:color-mix(in srgb,#78b799 11%,var(--journal-card))}.coverage-grid .is-covered{border-bottom:3px solid #b5ab70}.coverage-grid .is-danger{border-bottom:3px solid #cc7e83;background:color-mix(in srgb,#bb697a 7%,var(--journal-card))}.coverage-grid button[aria-expanded=true]{outline:2px solid var(--journal-accent);outline-offset:1px}.coverage-note{margin:15px 0 0;font-size:10px}.coverage-details{margin-top:12px;padding:13px 16px;border:1px solid var(--journal-border);border-radius:8px;background:var(--journal-soft)}.coverage-details h4{margin:0 0 10px;font-size:15px}.coverage-details p{margin:6px 0;display:flex;justify-content:space-between;gap:15px;font-size:11px}.coverage-details b{text-align:right;overflow-wrap:anywhere}@media(max-width:650px){.coverage-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.coverage-grid button{min-height:98px;padding:9px 4px}.coverage-intro{font-size:11px}.coverage-details p{font-size:10px}}
</style>
